 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, mix, color, smoothstep, oneMinus, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const visual = config.intent?.visualSpec ?? {};
  const colors = visual.colors ?? config.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const surface = colors.surface ?? '#0b0b10';

  const textItems = config.textContent ?? visual.textContent ?? [];

  const group = new THREE.Group();
  group.userData.handlers = {};

  const scene = config.scenePosition ?? {};
  const initialScale = scene.scale ?? [1, 1, 1];
  const initialPosition = scene.position ?? [0, 0, 0];
  const rotation = scene.rotation ?? [0, 0, 0];

  group.position.set(...initialPosition);
  group.rotation.set(...rotation);
  group.scale.set(...initialScale);

  let loadedImageTex = null;

  const size = 256;
  const grainBytes = new Uint8Array(size * size);
  for (let i = 0; i < grainBytes.length; i++) {
    grainBytes[i] = Math.random() * 255;
  }
  const grainTex = new THREE.DataTexture(grainBytes, size, size, THREE.LuminanceFormat, THREE.UnsignedByteType);
  grainTex.wrapS = THREE.RepeatWrapping;
  grainTex.wrapT = THREE.RepeatWrapping;
  grainTex.needsUpdate = true;

  const vUv = uv();
  const grad = mix(color(ink), color(surface), vUv.y);
  const bottomEdge = oneMinus(smoothstep(0.0, 0.12, vUv.y));
  const topEdge = smoothstep(0.88, 1.0, vUv.y);
  const accentMask = bottomEdge.add(topEdge);
  const gradAccent = mix(grad, color('#ff2a38'), accentMask.mul(0.12));

  const grain = texture(grainTex, vUv.mul(vec2(12.0, 9.0))).r.mul(0.06);
  const graded = mix(gradAccent, color(paper), grain);

  const bgGeo = new THREE.PlaneGeometry(4.4, 2.9);
  const bgMat = new MeshBasicNodeMaterial({
    colorNode: graded,
    transparent: true,
    opacity: 0.97,
    side: THREE.DoubleSide
  });
  const bg = new THREE.Mesh(bgGeo, bgMat);
  bg.position.z = -0.12;
  group.add(bg);

  const cardW = 4.0;
  const cardH = 2.5;
  const cardGeo = new THREE.PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({ color: 0xffffff, transparent: true });
  const card = new THREE.Mesh(cardGeo, cardMat);
  card.position.z = 0.05;
  group.add(card);

  const imageUrl = config.imageUrl ?? visual.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (!tex) return;
      tex.colorSpace = THREE.SRGBColorSpace;
      loadedImageTex = tex;
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    });
  }

  for (const item of textItems) {
    if (!item?.text) continue;
    const fontSize = item.typography?.fontSize ?? 31;
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: paper,
      align: 'center',
      maxWidthPx: 480
    });
    textObj.position.set(0, -cardH * 0.5 - 0.28, 0.15);
    group.add(textObj);
  }

  const targetY = group.position.y;
  group.position.y -= 0.35;
  group.scale.set(initialScale[0] * 0.94, initialScale[1] * 0.94, initialScale[2] * 0.94);

  const tl = gsap.timeline();
  tl.to(group.position, { y: targetY, duration: 0.75, ease: 'power3.out' }, 0);
  tl.to(group.scale, { x: initialScale[0], y: initialScale[1], z: initialScale[2], duration: 0.9, ease: 'power4.out' }, 0);

  group.userData.cleanup = () => {
    tl.kill();

    bgGeo.dispose();
    bgMat.dispose();

    cardGeo.dispose();
    cardMat.dispose();
    if (loadedImageTex) loadedImageTex.dispose();

    grainTex.dispose();

    let i = group.children.length;
    while (i--) {
      const child = group.children[i];
      if (child !== bg && child !== card) {
        group.remove(child);
      }
    }
  };

  return group;
}
